package com.yongdrel.payment_proof_service.application.service;
import com.yongdrel.payment_proof_service.adapter.out.persistence.*; import com.yongdrel.payment_proof_service.application.port.OrderOwnershipPort; import com.yongdrel.payment_proof_service.storage.PrivateProofStorage; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException; import java.io.*; import java.security.*; import java.util.*; import java.nio.file.Paths;
@Service public class PaymentProofService{
 private final PaymentProofRepository proofs; private final OrderOwnershipPort orders; private final PrivateProofStorage storage; private final long maxBytes;
 public PaymentProofService(PaymentProofRepository proofs,OrderOwnershipPort orders,PrivateProofStorage storage,@Value("${app.upload.max-bytes:5242880}")long maxBytes){this.proofs=proofs;this.orders=orders;this.storage=storage;this.maxBytes=maxBytes;}
 @Transactional public PaymentProofEntity submit(UUID order,UUID user,UUID tenant,String key,MultipartFile file){
  if(key==null||key.isBlank()||file==null||file.isEmpty()||file.getSize()>maxBytes)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid proof upload");
  Optional<PaymentProofEntity> existing=proofs.findByTenantIdAndUserIdAndIdempotencyKey(tenant,user,key);if(existing.isPresent())return existing.get();
  if(!orders.owns(order,user,tenant))throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Order ownership unavailable");
  String mime=signature(file);String ext=mime.equals("application/pdf")?".pdf":mime.equals("image/png")?".png":".jpg";String checksum=checksum(file);PrivateProofStorage.StoredFile saved=storage.save(file,ext);return proofs.save(new PaymentProofEntity(order,user,tenant,key,saved.key(),safeName(file.getOriginalFilename()),mime,checksum));
 }
 @Transactional public PaymentProofEntity verify(UUID id,UUID tenant,boolean accept){PaymentProofEntity p=proofs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Proof not found"));if(!p.getTenantId().equals(tenant))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Tenant mismatch");if(accept)p.accept();else p.reject();return p;}
 public PaymentProofEntity verifyMetadata(UUID id){return proofs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Proof not found"));}
 public boolean verifyReference(UUID order,UUID tenant,String reference){return proofs.findByOrderIdAndTenantIdAndIdempotencyKey(order,tenant,reference).map(p->p.getStatus()!=com.yongdrel.payment_proof_service.domain.model.ProofStatus.REJECTED).orElse(false);}
 public byte[] read(UUID id,UUID user,UUID tenant,boolean organizer){PaymentProofEntity p=proofs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Proof not found"));if(!tenant.equals(p.getTenantId())||(!organizer&&!user.equals(p.getUserId())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Proof access denied");return storage.read(p.getStorageKey());}
 private String signature(MultipartFile f){try(InputStream in=f.getInputStream()){byte[] b=in.readNBytes(8);if(b.length>=8&&b[0]==(byte)0x89&&b[1]==0x50&&b[2]==0x4e&&b[3]==0x47)return "image/png";if(b.length>=3&&b[0]==(byte)0xff&&b[1]==(byte)0xd8&&b[2]==(byte)0xff)return "image/jpeg";if(new String(b,0,Math.min(4,b.length),java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF"))return "application/pdf";}catch(IOException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unreadable proof");}throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported file signature");}
 private String checksum(MultipartFile f){try{MessageDigest d=MessageDigest.getInstance("SHA-256");return HexFormat.of().formatHex(d.digest(f.getBytes()));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Proof checksum failed");}}
 private String safeName(String name){if(name==null||name.isBlank())return "proof";String n=Paths.get(name).getFileName().toString();return n.length()>255?n.substring(0,255):n;}
}
